{
  "name": "NanoScan压电Z轴定位台",
  "name_en": "NanoScan Piezo Z Positioning Stage",
  "manufacturer": "Prior Scientific",
  "description": "NanoScan是一种压电驱动的Z轴纳米定位台或显微镜对焦平台，用于在微米至亚微米尺度上精确调节样品或物镜的轴向位置。它常用于显微成像、自动对焦、Z轴扫描、表面形貌测量及需要快速精密焦点控制的实验。",
  "description_en": "The NanoScan is a piezo-driven Z-axis nanopositioning stage or microscope focus stage used to precisely adjust the axial position of a sample or objective over micrometer-scale travel. It is commonly used for microscopy, autofocus, Z-scanning, surface profiling, and other experiments requiring fast and precise focus control.",
  "tag_hints": [
    "piezo positioning",
    "Z-axis stage",
    "microscope focus control",
    "nanopositioning",
    "autofocus",
    "Z scanning",
    "precision motion control"
  ],
  "actions": [
    {
      "action_name": "auto-isPortOpen",
      "description": "检查设备通信端口是否已打开。",
      "description_en": "Check whether the device communication port is open."
    },
    {
      "action_name": "auto-openPort",
      "description": "打开设备通信端口。",
      "description_en": "Open the device communication port."
    },
    {
      "action_name": "auto-closePort",
      "description": "关闭设备通信端口。",
      "description_en": "Close the device communication port."
    },
    {
      "action_name": "auto-sendCmd",
      "description": "向设备发送原始命令。",
      "description_en": "Send a raw command to the device."
    },
    {
      "action_name": "auto-getCmd",
      "description": "发送查询命令并读取设备返回值。",
      "description_en": "Send a query command and read the device response."
    },
    {
      "action_name": "auto-setCmd",
      "description": "向设备写入指定命令和值。",
      "description_en": "Write a specified command and value to the device."
    },
    {
      "action_name": "auto-getMovingState",
      "description": "获取平台运动状态。",
      "description_en": "Get the stage motion status."
    },
    {
      "action_name": "auto-getTravelRange",
      "description": "获取行程范围。",
      "description_en": "Get the travel range."
    },
    {
      "action_name": "auto-setTravelRange",
      "description": "设置行程范围。",
      "description_en": "Set the travel range."
    },
    {
      "action_name": "auto-getPositionRel",
      "description": "获取相对位置。",
      "description_en": "Get the relative position."
    },
    {
      "action_name": "auto-getPositionAbs",
      "description": "获取绝对位置。",
      "description_en": "Get the absolute position."
    },
    {
      "action_name": "auto-setPosition",
      "description": "定义当前位置显示值。",
      "description_en": "Define the current position value."
    },
    {
      "action_name": "auto-moveZeroPosition",
      "description": "移动到零位。",
      "description_en": "Move to the zero position."
    },
    {
      "action_name": "auto-moveAbsolutePosition",
      "description": "移动到指定绝对位置。",
      "description_en": "Move to a specified absolute position."
    },
    {
      "action_name": "auto-moveRelativePosition",
      "description": "按给定距离进行相对移动。",
      "description_en": "Move by a specified relative distance."
    },
    {
      "action_name": "auto-moveUp",
      "description": "向上移动一步或一个设定位移。",
      "description_en": "Move upward by one step or a defined increment."
    },
    {
      "action_name": "auto-moveDown",
      "description": "向下移动一步或一个设定位移。",
      "description_en": "Move downward by one step or a defined increment."
    },
    {
      "action_name": "auto-getStep",
      "description": "获取步进大小。",
      "description_en": "Get the step size."
    },
    {
      "action_name": "auto-setStep",
      "description": "设置步进大小。",
      "description_en": "Set the step size."
    },
    {
      "action_name": "auto-getVersion",
      "description": "获取设备版本信息。",
      "description_en": "Get the device version information."
    },
    {
      "action_name": "auto-resetStage",
      "description": "复位定位台。",
      "description_en": "Reset the positioning stage."
    }
  ]
}

